                                                                                                                                                                                                                    
  CREATE TABLE "JW_SYSTEM_DICT"                                                                                                                                                                      
   (	"SYSTEM_DICT_ID" NUMBER(20,0) GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 195 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" VARCHAR2(128),                                                                                                                                                                                        
	"CREATION_DATE" DATE DEFAULT SYSDATE,                                                                                                                                                                              
	"UPDATED_BY" VARCHAR2(128),                                                                                                                                                                                        
	"UPDATE_DATE" DATE,                                                                                                                                                                                                
	"CODE_VALUE" VARCHAR2(512),                                                                                                                                                                                        
	"TENANT_ID" NUMBER(20,0) DEFAULT 1,                                                                                                                                                                                
	"DICT_CODE" VARCHAR2(64),                                                                                                                                                                                          
	"REMARK" VARCHAR2(256),                                                                                                                                                                                            
	"DICT_TYPE" VARCHAR2(20) DEFAULT 'DEFAULT' NOT NULL ENABLE,                                                                                                                                                        
	"BUSINESS_TYPE" VARCHAR2(20),                                                                                                                                                                                      
	 PRIMARY KEY ("SYSTEM_DICT_ID")                                                                                                                                                                                    
  USING INDEX  ENABLE                                                                                                                                                                                               
   ) ;                                                                                                                                                                                                              

